#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

static const double PAYOFFS[6] = {660.0, 150.0, -1040.0, -4100.0, -9200.0, -14300.0};
static const double CHECK_COST = 20.0;

#define HT_BITS 20
#define HT_SIZE (1 << HT_BITS)
#define HT_MASK (HT_SIZE - 1)

typedef struct {
    uint8_t counts[18];
    uint8_t used;
    uint8_t best_act;
    double val;
} HashEntry;

static inline uint64_t hash_counts(const uint8_t c[18]) {
    uint64_t h = 14695981039346656037ULL;
    const uint64_t *p = (const uint64_t *)c;
    h ^= p[0];
    h *= 1099511628211ULL;
    h ^= p[1];
    h *= 1099511628211ULL;
    uint16_t tail = *(const uint16_t *)(c + 16);
    h ^= tail;
    h *= 1099511628211ULL;
    h ^= (h >> 33);
    return h;
}

typedef struct {
    const double (*P)[6][6]; // [3][6][6]
    HashEntry *ht;
    int use_pruning;
    uint64_t nodes_visited;
} SolverCtx;

static double dp_rec(SolverCtx *ctx, const double w[6], uint8_t counts[18], int rem, uint8_t *out_act) {
    double mass = w[0] + w[1] + w[2] + w[3] + w[4] + w[5];
    if (mass <= 0.0) {
        if (out_act) *out_act = 0;
        return 0.0;
    }

    double u_app = w[0]*PAYOFFS[0] + w[1]*PAYOFFS[1] + w[2]*PAYOFFS[2]
                 + w[3]*PAYOFFS[3] + w[4]*PAYOFFS[4] + w[5]*PAYOFFS[5];
    uint8_t stop_act = (u_app > 0.0) ? 1 : 0;
    double u_stop = (u_app > 0.0) ? u_app : 0.0;

    if (rem == 0) {
        if (out_act) *out_act = stop_act;
        return u_stop;
    }

    if (ctx->use_pruning) {
        double u_pi = w[0]*PAYOFFS[0] + w[1]*PAYOFFS[1];
        if (u_pi - u_stop <= CHECK_COST * mass) {
            if (out_act) *out_act = stop_act;
            return u_stop;
        }
    }

    uint64_t h = hash_counts(counts);
    size_t idx = (size_t)(h & HT_MASK);
    while (ctx->ht[idx].used) {
        if (memcmp(ctx->ht[idx].counts, counts, 18) == 0) {
            if (out_act) *out_act = ctx->ht[idx].best_act;
            return ctx->ht[idx].val;
        }
        idx = (idx + 1) & HT_MASK;
    }

    ctx->nodes_visited++;

    double best_val = u_stop;
    uint8_t best_act = stop_act;

    for (int k = 0; k < 3; k++) {
        double q_k = -CHECK_COST * mass;
        // Also track tighter upper bound across remaining bands y..5!
        // Remaining PI mass starts as u_pi; after each y we replace u_pi(w_y) with actual val_y <= u_pi(w_y)
        double rem_upper = (w[0]*PAYOFFS[0] + w[1]*PAYOFFS[1]) - CHECK_COST * mass;
        int pruned_k = 0;
        for (int y = 0; y < 6; y++) {
            double wy[6];
            for (int s = 0; s < 6; s++) {
                wy[s] = w[s] * ctx->P[k][s][y];
            }
            double wy_pi = wy[0]*PAYOFFS[0] + wy[1]*PAYOFFS[1];
            counts[k * 6 + y]++;
            double vy = dp_rec(ctx, wy, counts, rem - 1, NULL);
            counts[k * 6 + y]--;
            q_k += vy;
            rem_upper += (vy - wy_pi);
            if (ctx->use_pruning && rem_upper <= best_val - 1e-12) {
                pruned_k = 1;
                break;
            }
        }
        if (!pruned_k && q_k > best_val) {
            best_val = q_k;
            best_act = (uint8_t)(2 + k);
        }
    }

    // Insert into hash table (re-probe in case children inserted into idx!)
    idx = (size_t)(h & HT_MASK);
    while (ctx->ht[idx].used) {
        idx = (idx + 1) & HT_MASK;
    }
    memcpy(ctx->ht[idx].counts, counts, 18);
    ctx->ht[idx].used = 1;
    ctx->ht[idx].best_act = best_act;
    ctx->ht[idx].val = best_val;

    if (out_act) *out_act = best_act;
    return best_val;
}

// Compute all 5 root unnormalized Q-values: [decline, approve, bureau, income, bank]
void solve_root_q(const double P_flat[108], const double w0[6], int rem, int use_pruning, double out_q[5], uint64_t *out_nodes) {
    const double (*P)[6][6] = (const double (*)[6][6])P_flat;
    double mass = w0[0] + w0[1] + w0[2] + w0[3] + w0[4] + w0[5];
    out_q[0] = 0.0;
    out_q[1] = w0[0]*PAYOFFS[0] + w0[1]*PAYOFFS[1] + w0[2]*PAYOFFS[2]
             + w0[3]*PAYOFFS[3] + w0[4]*PAYOFFS[4] + w0[5]*PAYOFFS[5];
    if (rem <= 0 || mass <= 0.0) {
        out_q[2] = -1e30;
        out_q[3] = -1e30;
        out_q[4] = -1e30;
        if (out_nodes) *out_nodes = 0;
        return;
    }

    HashEntry *ht = (HashEntry *)calloc(HT_SIZE, sizeof(HashEntry));
    SolverCtx ctx;
    ctx.P = P;
    ctx.ht = ht;
    ctx.use_pruning = use_pruning;
    ctx.nodes_visited = 0;

    uint8_t counts[18];
    memset(counts, 0, 18);

    for (int k = 0; k < 3; k++) {
        double q_k = -CHECK_COST * mass;
        for (int y = 0; y < 6; y++) {
            double wy[6];
            for (int s = 0; s < 6; s++) {
                wy[s] = w0[s] * P[k][s][y];
            }
            counts[k * 6 + y]++;
            q_k += dp_rec(&ctx, wy, counts, rem - 1, NULL);
            counts[k * 6 + y]--;
        }
        out_q[2 + k] = q_k;
    }

    if (out_nodes) *out_nodes = ctx.nodes_visited;
    free(ht);
}

// Batch solve V*(b_0, rem) for M models x A applicants
void solve_vstar_batch(const double *P_batch, int M, const double *priors, int A, int rem, double *out_vstar) {
    HashEntry *ht = (HashEntry *)malloc(HT_SIZE * sizeof(HashEntry));
    uint8_t counts[18];
    for (int m = 0; m < M; m++) {
        const double (*P)[6][6] = (const double (*)[6][6])(P_batch + m * 108);
        for (int a = 0; a < A; a++) {
            memset(ht, 0, HT_SIZE * sizeof(HashEntry));
            memset(counts, 0, 18);
            SolverCtx ctx = {P, ht, 1, 0};
            const double *w0 = priors + a * 6;
            out_vstar[m * A + a] = dp_rec(&ctx, w0, counts, rem, NULL);
        }
    }
    free(ht);
}

// Evaluate policy induced by P_pol under M true models P_true_batch for A applicants!
//Wait: how does policy P_pol act? Using its own DP!
// Even better: build the deterministic policy tree for applicant `a` under P_pol ONCE, then evaluate on all M models!
typedef struct {
    uint8_t act; // 0=decline, 1=approve, 2..4=check k
    int children[6];
} PolNode;

typedef struct {
    PolNode *nodes;
    int size;
    int cap;
} PolTree;

static int build_pol_tree_rec(SolverCtx *pol_ctx, PolTree *tree, const double w_pol[6], uint8_t counts[18], int rem) {
    uint8_t act = 0;
    dp_rec(pol_ctx, w_pol, counts, rem, &act);
    if (tree->size >= tree->cap) {
        tree->cap *= 2;
        tree->nodes = (PolNode *)realloc(tree->nodes, tree->cap * sizeof(PolNode));
    }
    int my_idx = tree->size++;
    tree->nodes[my_idx].act = act;
    if (act < 2 || rem == 0) {
        for (int y = 0; y < 6; y++) tree->nodes[my_idx].children[y] = -1;
        return my_idx;
    }
    int k = act - 2;
    for (int y = 0; y < 6; y++) {
        double wy[6];
        for (int s = 0; s < 6; s++) wy[s] = w_pol[s] * pol_ctx->P[k][s][y];
        double mass_y = wy[0]+wy[1]+wy[2]+wy[3]+wy[4]+wy[5];
        if (mass_y <= 0.0) {
            // Unreachable under P_pol; if reached under P_true, fallback to prior/stop
            tree->nodes[my_idx].children[y] = -1;
        } else {
            counts[k * 6 + y]++;
            int ch = build_pol_tree_rec(pol_ctx, tree, wy, counts, rem - 1);
            counts[k * 6 + y]--;
            tree->nodes[my_idx].children[y] = ch;
        }
    }
    return my_idx;
}

static double eval_pol_tree_rec(const PolTree *tree, int idx, const double P_true[3][6][6], const double w_true[6]) {
    double mass = w_true[0]+w_true[1]+w_true[2]+w_true[3]+w_true[4]+w_true[5];
    if (mass <= 0.0) return 0.0;
    if (idx < 0) {
        // Fallback if P_pol had 0 prob: stop greedily on w_true
        double u_app = w_true[0]*PAYOFFS[0] + w_true[1]*PAYOFFS[1] + w_true[2]*PAYOFFS[2]
                     + w_true[3]*PAYOFFS[3] + w_true[4]*PAYOFFS[4] + w_true[5]*PAYOFFS[5];
        return (u_app > 0.0) ? u_app : 0.0;
    }
    uint8_t act = tree->nodes[idx].act;
    if (act == 0) return 0.0;
    if (act == 1) {
        return w_true[0]*PAYOFFS[0] + w_true[1]*PAYOFFS[1] + w_true[2]*PAYOFFS[2]
             + w_true[3]*PAYOFFS[3] + w_true[4]*PAYOFFS[4] + w_true[5]*PAYOFFS[5];
    }
    int k = act - 2;
    double total = -CHECK_COST * mass;
    for (int y = 0; y < 6; y++) {
        double wy[6];
        for (int s = 0; s < 6; s++) wy[s] = w_true[s] * P_true[k][s][y];
        total += eval_pol_tree_rec(tree, tree->nodes[idx].children[y], P_true, wy);
    }
    return total;
}

void eval_policy_batch(const double P_pol_flat[108], const double *P_true_batch, int M, const double *priors, int A, int rem, double *out_vpol) {
    HashEntry *ht = (HashEntry *)malloc(HT_SIZE * sizeof(HashEntry));
    const double (*P_pol)[6][6] = (const double (*)[6][6])P_pol_flat;
    uint8_t counts[18];

    for (int a = 0; a < A; a++) {
        memset(ht, 0, HT_SIZE * sizeof(HashEntry));
        memset(counts, 0, 18);
        SolverCtx pol_ctx = {P_pol, ht, 1, 0};
        PolTree tree;
        tree.cap = 1024;
        tree.size = 0;
        tree.nodes = (PolNode *)malloc(tree.cap * sizeof(PolNode));
        const double *w0 = priors + a * 6;
        build_pol_tree_rec(&pol_ctx, &tree, w0, counts, rem);

        for (int m = 0; m < M; m++) {
            const double (*P_true)[6][6] = (const double (*)[6][6])(P_true_batch + m * 108);
            out_vpol[m * A + a] = eval_pol_tree_rec(&tree, 0, P_true, w0);
        }
        free(tree.nodes);
    }
    free(ht);
}

