    out_q[1] = w0[0]*PAYOFFS[0] + w0[1]*PAYOFFS[1] + w0[2]*PAYOFFS[2]
             + w0[3]*PAYOFFS[3] + w0[4]*PAYOFFS[4] + w0[5]*PAYOFFS[5];
    if (rem <= 0 || mass <= 0.0) {
        out_q[2] = -1e30;
        out_q[3] = -1e30;
        out_q[4] = -1e30;
        if (out_nodes) *out_nodes = 0;
        return;
    }

    HashEntry *ht = (HashEntry *)calloc(HT_SIZE, sizeof(HashEntry));
    SolverCtx ctx = {P, ht, 1, use_pruning, 0};

    uint8_t counts[18];
    memset(counts, 0, 18);

    for (int k = 0; k < 3; k++) {
        double q_k = -CHECK_COST * mass;
        for (int y = 0; y < 6; y++) {
