            }
            counts[k * 6 + y]++;
            q_k += dp_rec(&ctx, wy, counts, rem - 1, NULL);
            counts[k * 6 + y]--;
        }
        out_q[2 + k] = q_k;
    }

    if (out_nodes) *out_nodes = ctx.nodes_visited;
    free(ht);
}

