# Also inspect expected number of checks of each kind used under P_bar across the 20 applicants!
def count_expected_checks(P, w, rem):
    # Monte Carlo or exact recursion on P_bar
    q, _ = solve_root_q(P, w, rem, True)
    act = int(np.argmax(q))
    if act < 2 or rem == 0:
        return np.zeros(3)
    k = act - 2
    mass = np.sum(w)
    cnt = np.zeros(3)
    cnt[k] += mass
    for y in range(6):
        wy = w * P[k, :, y]
        if np.sum(wy) > 1e-9:
            cnt += count_expected_checks(P, wy, rem - 1)
    return cnt

